const getTouristShortId = (id: string) => {
  const lowerId = id.toLowerCase()
  if (lowerId.includes('-official-')) {
    const parts = lowerId.split('-official-')
    if (parts.length > 1) {
      const rest = parts[1]
      return rest.replace(/-ida$/, '').replace(/-vuelta$/, '')
    }
  }
  return lowerId
}

