type Panel = 'map' | 'favourites' | 'settings' | 'profile'

interface UserPrefs {
  favBusLines: string[]
  favStops: string[]
  notifyNearbyBus: boolean
  notifyNearbyRadius: number
  notifyFavLines: boolean
  darkMap: boolean
  language: 'es' | 'en'
  fontSize: 'normal' | 'large'
  textScale?: number
  showPassengerCount: boolean
  autoZoomOnBus: boolean
  favBuses?: string[]
  favDrivers?: string[]
  filterByPassengers?: boolean
  maxPassengers?: number
  savedTrips?: any[]
}

const DEFAULT_PREFS: UserPrefs = {
  favBusLines: [], favStops: [],
  notifyNearbyBus: true, notifyNearbyRadius: 0.5, notifyFavLines: true,
  darkMap: false, language: 'es', fontSize: 'normal', textScale: 1.0,
  showPassengerCount: true, autoZoomOnBus: true,
  favBuses: [], favDrivers: [],
  filterByPassengers: false,
  maxPassengers: 10,
  savedTrips: []
}

function loadPrefs(): UserPrefs {
  if (typeof window === 'undefined') return DEFAULT_PREFS
  try {
    const raw = localStorage.getItem('bienparada_user_prefs')
    return raw ? { ...DEFAULT_PREFS, ...JSON.parse(raw) } : DEFAULT_PREFS
  } catch { return DEFAULT_PREFS }
}
function savePrefs(p: UserPrefs) { localStorage.setItem('bienparada_user_prefs', JSON.stringify(p)) }

