  // Fetch street-aligned walking routes (OSRM driving, matching vehicle flow) with L-shaped grid fallbacks
  useEffect(() => {
    if (!originCoord || !destCoord) {
      setWalkingPath1([])
      setWalkingPath2([])
      return
    }

    const currentRoute = activeTravelRoute || travelRoute
    if (!currentRoute) {
      setWalkingPath1([])
      setWalkingPath2([])
      return
    }

    const getGridFallbackPath = (p1: { lat: number; lng: number }, p2: { lat: number; lng: number }) => {
      return [
        { lat: p1.lat, lng: p1.lng },
        { lat: p1.lat, lng: p2.lng }, // Corner point (aligned horizontally first)
        { lat: p2.lat, lng: p2.lng }
      ]
    }

    const oStop = currentRoute.originStop
    const url1 = `https://router.project-osrm.org/route/v1/driving/${originCoord.lng},${originCoord.lat};${oStop.longitude},${oStop.latitude}?overview=full&geometries=geojson`
    fetch(url1)
      .then(res => res.json())
      .then(data => {
        if (data.routes && data.routes[0] && data.routes[0].geometry) {
          const coords = data.routes[0].geometry.coordinates.map((c: number[]) => ({ lat: c[1], lng: c[0] }))
          setWalkingPath1(coords)
        } else {
          setWalkingPath1(getGridFallbackPath(originCoord, { lat: oStop.latitude, lng: oStop.longitude }))
        }
      })
      .catch(() => {
        setWalkingPath1(getGridFallbackPath(originCoord, { lat: oStop.latitude, lng: oStop.longitude }))
      })

    const dStop = currentRoute.destStop
    const url2 = `https://router.project-osrm.org/route/v1/driving/${dStop.longitude},${dStop.latitude};${destCoord.lng},${destCoord.lat}?overview=full&geometries=geojson`
    fetch(url2)
      .then(res => res.json())
      .then(data => {
        if (data.routes && data.routes[0] && data.routes[0].geometry) {
          const coords = data.routes[0].geometry.coordinates.map((c: number[]) => ({ lat: c[1], lng: c[0] }))
          setWalkingPath2(coords)
        } else {
          setWalkingPath2(getGridFallbackPath({ lat: dStop.latitude, lng: dStop.longitude }, destCoord))
        }
      })
      .catch(() => {
        setWalkingPath2(getGridFallbackPath({ lat: dStop.latitude, lng: dStop.longitude }, destCoord))
      })
  }, [originCoord, destCoord, activeTravelRoute, travelRoute])

